content:
:root {
  --primary-color: #2563eb;
  --primary-hover: #1d4ed8;
  --bg-color: #f8fafc;
  --card-bg: #ffffff;
  --text-main: #1e293b;
  --text-muted: #64748b;
  --border-color: #e2e8f0;
  --shadow: 0 4px 6px -1px rgb(0 0 0 / 0.1), 0 2px 4px -2px rgb(0 0 0 / 0.1);
  --radius: 12px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  background-color: var(--bg-color);
  color: var(--text-main);
  line-height: 1.5;
}

.app-container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 2rem 1rem;
}

.header {
  margin-bottom: 2rem;
  text-align: center;
}

.title {
  font-size: 2rem;
  font-weight: 700;
  color: var(--text-main);
}

.simulator-layout {
  display: grid;
  grid-template-columns: 1fr;
  gap: 2rem;
}

@media (min-width: 768px) {
  .simulator-layout {
    grid-template-columns: 350px 1fr;
  }
}

.input-section {
  background: var(--card-bg);
  padding: 1.5rem;
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
  height: fit-content;
}

.input-group {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.label {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--text-main);
}

.input-field {
  width: 100%;
  padding: 0.75rem;
  font-size: 1rem;
  border: 1px solid var(--border-color);
  border-radius: 6px;
  outline: none;
  transition: border-color 0.2s, box-shadow 0.2s;
}

.input-field:focus {
  border-color: var(--primary-color);
  box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.15);
}

.range-slider {
  width: 100%;
  accent-color: var(--primary-color);
  cursor: pointer;
}

.results-section {
  display: flex;
  flex-direction: column;
  gap: 2rem;
}

.summary-cards {
  display: grid;
  grid-template-columns: 1fr;
  gap: 1rem;
}

@media (min-width: 640px) {
  .summary-cards {
    grid-template-columns: repeat(3, 1fr);
  }
}

.card {
  background: var(--card-bg);
  padding: 1.25rem;
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.card-title {
  font-size: 0.875rem;
  color: var(--text-muted);
  font-weight: 500;
}

.card-value {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--primary-color);
}

.chart-section {
  background: var(--card-bg);
  padding: 1.5rem;
  border-radius: var(--radius);
  box-shadow: var(--shadow);
}

.chart-title {
  font-size: 1.125rem;
  font-weight: 600;
  color: var(--text-main);
  margin-bottom: 1rem;
}

export interface LoanInputs {
  loanAmount: number;
  interestRate: number;
  loanYears: number;
}

export interface YearlySchedule {
  year: number;
  principalPayment: number;
  interestPayment: number;
  remainingBalance: number;
}

import { useState, useMemo } from 'react';
import {
  BarChart,
  Bar,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
  ResponsiveContainer
} from 'recharts';
import { LoanInputs, YearlySchedule } from './types';
import './index.css';

export default function App() {
  const [inputs, setInputs] = useState<LoanInputs>({
    loanAmount: 3000, // 万円
    interestRate: 1.5, // %
    loanYears: 35, // 年
  });

  const handleInputChange = (field: keyof LoanInputs, value: number) => {
    setInputs(prev => ({ ...prev, [field]: value }));
  };

  const { monthlyPayment, totalPayment, totalInterest, yearlySchedule } = useMemo(() => {
    const principal = inputs.loanAmount * 10000; // 円に変換
    const monthlyRate = inputs.interestRate / 100 / 12;
    const totalMonths = inputs.loanYears * 12;

    let monthly = 0;
    if (monthlyRate === 0) {
      monthly = principal / totalMonths;
    } else {
      monthly =
        (principal * monthlyRate * Math.pow(1 + monthlyRate, totalMonths)) /
        (Math.pow(1 + monthlyRate, totalMonths) - 1);
    }

    let currentBalance = principal;
    let totalInt = 0;
    const schedule: YearlySchedule[] = [];

    for (let year = 1; year <= inputs.loanYears; year++) {
      let yearlyPrincipal = 0;
      let yearlyInterest = 0;

      for (let m = 0; m < 12; m++) {
        if (currentBalance <= 0) break;
        const interestForMonth = currentBalance * monthlyRate;
        let principalForMonth = monthly - interestForMonth;

        if (principalForMonth > currentBalance) {
          principalForMonth = currentBalance;
        }

        yearlyInterest += interestForMonth;
        yearlyPrincipal += principalForMonth;
        currentBalance -= principalForMonth;
      }

      totalInt += yearlyInterest;
      schedule.push({
        year,
        principalPayment: Math.round(yearlyPrincipal),
        interestPayment: Math.round(yearlyInterest),
        remainingBalance: Math.max(0, Math.round(currentBalance)),
      });
    }

    const tPayment = principal + totalInt;

    return {
      monthlyPayment: Math.round(monthly),
      totalPayment: Math.round(tPayment),
      totalInterest: Math.round(totalInt),
      yearlySchedule: schedule,
    };
  }, [inputs]);

  const formatCurrency = (amount: number) => {
    return new Intl.NumberFormat('ja-JP', { style: 'currency', currency: 'JPY' }).format(amount);
  };

  return (
    <div className="app-container">
      <header className="header">
        <h1 className="title">住宅ローンシミュレーター</h1>
      </header>

      <div className="simulator-layout">
        <div className="input-section">
          <div className="input-group">
            <label className="label">借入金額 (万円): {inputs.loanAmount}万円</label>
            <input
              type="number"
              className="input-field"
              value={inputs.loanAmount}
              onChange={(e) => handleInputChange('loanAmount', Number(e.target.value))}
              min={100}
              max={20000}
              step={100}
            />
            <input
              type="range"
              className="range-slider"
              value={inputs.loanAmount}
              onChange={(e) => handleInputChange('loanAmount', Number(e.target.value))}
              min={100}
              max={10000}
              step={50}
            />
          </div>

          <div className="input-group">
            <label className="label">金利 (%): {inputs.interestRate}%</label>
            <input
              type="number"
              className="input-field"
              value={inputs.interestRate}
              onChange={(e) => handleInputChange('interestRate', Number(e.target.value))}
              min={0.1}
              max={10}
              step={0.1}
            />
            <input
              type="range"
              className="range-slider"
              value={inputs.interestRate}
              onChange={(e) => handleInputChange('interestRate', Number(e.target.value))}
              min={0.1}
              max={5}
              step={0.1}
            />
          </div>

          <div className="input-group">
            <label className="label">返済期間 (年): {inputs.loanYears}年</label>
            <input
              type="number"
              className="input-field"
              value={inputs.loanYears}
              onChange={(e) => handleInputChange('loanYears', Number(e.target.value))}
              min={1}
              max={50}
              step={1}
            />
            <input
              type="range"
              className="range-slider"
              value={inputs.loanYears}
              onChange={(e) => handleInputChange('loanYears', Number(e.target.value))}
              min={1}
              max={50}
              step={1}
            />
          </div>
        </div>

        <div className="results-section">
          <div className="summary-cards">
            <div className="card">
              <span className="card-title">毎月の返済額</span>
              <span className="card-value">{formatCurrency(monthlyPayment)}</span>
            </div>
            <div className="card">
              <span className="card-title">総返済額</span>
              <span className="card-value">{formatCurrency(totalPayment)}</span>
            </div>
            <div className="card">
              <span className="card-title">総利息額</span>
              <span className="card-value">{formatCurrency(totalInterest)}</span>
            </div>
          </div>

          <div className="chart-section">
            <h2 className="chart-title">年ごとの返済推移（元本・利息）</h2>
            <div style={{ width: '100%', height: 350 }}>
              <ResponsiveContainer>
                <BarChart data={yearlySchedule}>
                  <CartesianGrid strokeDasharray="3 3" />
                  <XAxis dataKey="year" tickFormatter={(val) => `${val}年`} />
                  <YAxis tickFormatter={(val) => `${Math.round(val / 10000)}万円`} />
                  <Tooltip
                    formatter={(value: any) => formatCurrency(Number(value))}
                    labelFormatter={(label) => `${label}年目`}
                  />
                  <Legend />
                  <Bar dataKey="principalPayment" name="元本返済" stackId="a" fill="#2563eb" />
                  <Bar dataKey="interestPayment" name="利息返済" stackId="a" fill="#93c5fd" />
                </BarChart>
              </ResponsiveContainer>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}
